  as_draws_df(fits$fit_base),
  rhat = posterior::rhat,
  ess_bulk = posterior::ess_bulk
) |>
  filter(!grepl("^lp__|^lprior", variable)) |>
  transmute(
    Parameter = variable,
    `R̂` = sprintf("%.3f", rhat),
    ESS_bulk = sprintf("%.0f", ess_bulk)
  ) |>
  gt()
