obs_gneg_cp <- es_gneg_cut |> mutate(or = exp(yi), w = 1 / sei)

ggplot(pred_gneg, aes(x = cutpoint, y = median_OR)) +
  annotate("rect", xmin = min(roc_cuts_gneg), xmax = max(roc_cuts_gneg),
           ymin = -Inf, ymax = Inf, fill = "#d4e8f7", alpha = 0.6) +
