::: {#cell-fig-gpos-cutpoint .cell}

```{.r .cell-code .hidden}
#| label: fig-gpos-cutpoint
#| fig-cap: "TTP cutpoint dose-response for Gram-positive bacteremia. Red curve = full model (8–72 h); dashed gray = sensitivity excluding Minejima2019 (72 h), which uses a biologically distinct definition of prolonged bacteremia. Blue points are 2×2-derived effect sizes. Orange zone = range of ROC-derived cutpoints from Gram-positive studies (9–13 h). The negative slope in the full model is driven almost entirely by Minejima2019; after exclusion the slope becomes uncertain (P[slope < 0] = 75%)."

obs_gpos_cp <- es_gpos_cut |>
  filter(ttp_cutpoint_hours <= 30) |>
  mutate(or = exp(yi), w = 1 / sei)

ggplot(pred_gpos_cp, aes(x = cutpoint, y = median_OR)) +
  annotate("rect", xmin = min(roc_cuts_gpos), xmax = max(roc_cuts_gpos),
           ymin = -Inf, ymax = Inf, fill = "#f7e4d4", alpha = 0.65) +
  annotate("text", x = mean(range(roc_cuts_gpos)), y = 12,
           label = "ROC-derived range\n(9–13 h)", size = 3,
           color = "#b35900", fontface = "italic") +
  geom_ribbon(aes(ymin = lo, ymax = hi), fill = "#E41A1C", alpha = 0.15, color = NA) +
  geom_line(color = "#b22222", linewidth = 1.3) +
  geom_ribbon(data = pred_gpos_sens_cp,
              aes(ymin = lo, ymax = hi), fill = "gray60", alpha = 0.12, color = NA) +
  geom_line(data = pred_gpos_sens_cp,
            color = "gray40", linewidth = 0.9, linetype = "dashed") +
  geom_hline(yintercept = 1, linetype = "dashed", color = "red") +
  geom_point(data = obs_gpos_cp,
             aes(x = ttp_cutpoint_hours, y = or, size = w),
             alpha = 0.65, color = "#1a7bbf", inherit.aes = FALSE) +
  # Flag truncated 72h outlier
  annotate("point", x = 30, y = exp(-1.06), size = 4, color = "gray50", shape = 17) +
  annotate("text", x = 29.5, y = 0.5,
           label = "Minejima2019\n(72 h, truncated →)", size = 2.6,
           color = "gray40", hjust = 1) +
  scale_size_continuous(range = c(2, 8), guide = "none") +
  scale_y_continuous(limits = c(0.3, 14), trans = "log10",
                     breaks = c(0.5, 1, 2, 3, 4, 6, 8, 12)) +
  scale_x_continuous(breaks = seq(0, 30, 4), limits = c(6, 30)) +
  labs(x = "TTP cutpoint (hours)",
       y = "OR for mortality (short vs long TTP, log scale)") +
  theme_minimal() +
  theme(panel.grid.minor = element_blank())
