#| label: continuous-dr-setup
#| include: false
# ---- Log-normal TTP distribution helpers ----
make_E_ttp <- function(mu, sigma) {
  list(
    short = function(c) {
      exp(mu + sigma^2/2) *
        pnorm((log(c) - mu - sigma^2) / sigma) /
        pnorm((log(c) - mu) / sigma)
    },
    long  = function(c) {
      exp(mu + sigma^2/2) *
        (1 - pnorm((log(c) - mu - sigma^2) / sigma)) /
        (1 - pnorm((log(c) - mu) / sigma))
    }
  )
}

ttp_fn_gneg <- make_E_ttp(log(13), 0.55)
ttp_fn_gpos <- make_E_ttp(log(15), 0.55)

# ---- Build dose-response datasets ----
build_dose_df <- function(es_cut, ttp_fn) {
  es_cut |>
    select(study_id, ttp_cutpoint_hours,
           events_short_ttp, n_short_ttp,
           events_long_ttp,  n_long_ttp) |>
    distinct() |>
    mutate(rep_ttp_short = map_dbl(ttp_cutpoint_hours, ttp_fn$short),
           rep_ttp_long  = map_dbl(ttp_cutpoint_hours, ttp_fn$long))
}

dose_df_gneg <- build_dose_df(
  es_gneg_cut |> filter(study_id != "Prinsloo2023"), ttp_fn_gneg)
dose_df_gpos <- build_dose_df(
  es_gpos_cut |> filter(study_id != "Minejima2019"), ttp_fn_gpos)

build_dose_long <- function(dose_df) {
  bind_rows(
    dose_df |> transmute(study_id, rep_ttp = rep_ttp_short,
                         events = events_short_ttp, n = n_short_ttp),
    dose_df |> transmute(study_id, rep_ttp = rep_ttp_long,
                         events = events_long_ttp,  n = n_long_ttp)
  ) |>
    mutate(non_events = n - events, log_ttp = log(rep_ttp))
}

dose_long_gneg <- build_dose_long(dose_df_gneg)
dose_long_gpos <- build_dose_long(dose_df_gpos)

# ---- Fit GLMMs ----
fit_dr_gneg <- glmer(cbind(events, non_events) ~ log_ttp + (1 | study_id),
                     data = dose_long_gneg, family = binomial)
fit_dr_gpos <- glmer(cbind(events, non_events) ~ log_ttp + (1 | study_id),
                     data = dose_long_gpos, family = binomial)

b1_gneg  <- fixef(fit_dr_gneg)[2]
b1_gpos  <- fixef(fit_dr_gpos)[2]
vc_gneg  <- vcov(fit_dr_gneg)
vc_gpos  <- vcov(fit_dr_gpos)

# ---- Simulation draws for CI propagation ----
set.seed(9183)
n_sim      <- 4000
sims_gneg  <- MASS::mvrnorm(n_sim, mu = fixef(fit_dr_gneg), Sigma = vc_gneg)
sims_gpos  <- MASS::mvrnorm(n_sim, mu = fixef(fit_dr_gpos), Sigma = vc_gpos)

# ---- Predicted OR curves (relative to 24 h reference) ----
ref_ttp  <- 24
ttp_seq  <- exp(seq(log(2), log(36), length.out = 200))

make_or_curve <- function(sims, ref = 24) {
  map_dfr(ttp_seq, function(t) {
    logOR <- sims[,1] + sims[,2] * log(t) -
             (sims[,1] + sims[,2] * log(ref))
    tibble(ttp = t, median_OR = median(exp(logOR)),
           lo  = quantile(exp(logOR), 0.025),
           hi  = quantile(exp(logOR), 0.975))
  })
}
curve_gneg <- make_or_curve(sims_gneg) |> mutate(gram = "Gram-negative")
curve_gpos <- make_or_curve(sims_gpos) |> mutate(gram = "Gram-positive")

# ---- Anchor statistics from observed 2x2 data ----
calc_anchor <- function(dose_df_in) {
  list(
    mort = (sum(dose_df_in$events_short_ttp) + sum(dose_df_in$events_long_ttp)) /
           (sum(dose_df_in$n_short_ttp)      + sum(dose_df_in$n_long_ttp)),
    ref_ttp = (sum(dose_df_in$n_short_ttp * dose_df_in$rep_ttp_short) +
               sum(dose_df_in$n_long_ttp  * dose_df_in$rep_ttp_long)) /
              (sum(dose_df_in$n_short_ttp) + sum(dose_df_in$n_long_ttp)),
    n_deaths  = sum(dose_df_in$events_short_ttp) + sum(dose_df_in$events_long_ttp),
    n_pts     = sum(dose_df_in$n_short_ttp)      + sum(dose_df_in$n_long_ttp),
    n_studies = n_distinct(dose_df_in$study_id)
  )
}

anc_gneg <- calc_anchor(dose_df_gneg)
anc_gpos <- calc_anchor(dose_df_gpos)

# ---- Absolute mortality curves ----
make_abs_curve <- function(sims, anchor) {
  map_dfr(ttp_seq, function(t) {
    p <- plogis(qlogis(anchor$mort) +
                sims[,2] * (log(t) - log(anchor$ref_ttp)))
    tibble(ttp = t,
           median_p = median(p),
           lo = quantile(p, 0.025),
           hi = quantile(p, 0.975))
  })
}
abs_gneg <- make_abs_curve(sims_gneg, anc_gneg) |> mutate(gram = "Gram-negative")
abs_gpos <- make_abs_curve(sims_gpos, anc_gpos) |> mutate(gram = "Gram-positive")

# ---- Panel builder functions ----
make_or_panel <- function(curve_data, col, title_label) {
  ggplot(curve_data, aes(x = ttp, y = median_OR)) +
    geom_ribbon(aes(ymin = lo, ymax = hi), fill = col, alpha = 0.15, color = NA) +
    geom_line(color = col, linewidth = 1.3) +
    geom_hline(yintercept = 1, linetype = "dashed",
               color = "gray40", linewidth = 0.6) +
    scale_x_continuous(breaks = c(4, 8, 12, 16, 20, 24, 30, 36),
                       limits = c(1.5, 37),
                       name   = "Time to positivity (hours)") +
    scale_y_continuous(limits = c(0, 8.5), breaks = 0:8,
                       name   = "OR for mortality vs TTP = 24 h") +
    labs(title = title_label) +
    theme_minimal(base_size = 10) +
    theme(panel.grid.minor = element_blank(),
          plot.title = element_text(face = "bold", size = 10))
}

make_prob_panel <- function(abs_data, obs_pts, col, anchor,
                             anchor_label, title_label) {
  obs_clean <- obs_pts |> filter(mort > 0, mort < 1)
  ggplot(abs_data, aes(x = ttp, y = median_p * 100)) +
    geom_ribbon(aes(ymin = lo * 100, ymax = hi * 100),
                fill = col, alpha = 0.15, color = NA) +
    geom_line(color = col, linewidth = 1.3) +
    geom_hline(yintercept = anchor$mort * 100, linetype = "dashed",
               color = "gray40", linewidth = 0.6) +
    geom_point(aes(x = anchor$ref_ttp, y = anchor$mort * 100),
               color = col, size = 3.5, shape = 18, inherit.aes = FALSE) +
    geom_point(data = obs_clean,
               aes(x = rep_ttp, y = mort * 100),
               color = col, size = 2, alpha = 0.55, shape = 16,
               inherit.aes = FALSE) +
    annotate("text", x = 36, y = 63, label = anchor_label,
             size = 2.6, color = "gray25", hjust = 1, vjust = 1,
             lineheight = 1.35) +
    scale_x_continuous(breaks = c(4, 8, 12, 16, 20, 24, 30, 36),
                       limits = c(1.5, 37),
                       name   = "Time to positivity (hours)") +
    scale_y_continuous(limits = c(0, 65), breaks = seq(0, 60, 10),
                       labels = function(x) paste0(x, "%"),
                       name   = "Predicted mortality probability") +
    labs(title = title_label) +
    theme_minimal(base_size = 10) +
    theme(panel.grid.minor = element_blank(),
          plot.title = element_text(face = "bold", size = 10))
}

# Observed group-level mortality rates for probability panels
obs_pts_gneg <- dose_long_gneg |> mutate(mort = events / n)
obs_pts_gpos <- dose_long_gpos |> mutate(mort = events / n)

p_or_gneg   <- make_or_panel(curve_gneg, "#E41A1C",
                              "A  Gram-negative: OR vs TTP = 24 h")
p_prob_gneg <- make_prob_panel(
  abs_gneg, obs_pts_gneg, "#E41A1C", anc_gneg,
  sprintf("Anchor: %.1f%% at %.1f h\n%d deaths / %s patients\n%d studies\n(patient-weighted mean TTP)",
          anc_gneg$mort * 100, anc_gneg$ref_ttp,
          anc_gneg$n_deaths, format(anc_gneg$n_pts, big.mark = ","),
          anc_gneg$n_studies),
  "B  Gram-negative: absolute mortality probability"
)
p_or_gpos   <- make_or_panel(curve_gpos, "#377EB8",
                              "C  Gram-positive: OR vs TTP = 24 h")
p_prob_gpos <- make_prob_panel(
  abs_gpos, obs_pts_gpos, "#377EB8", anc_gpos,
  sprintf("Anchor: %.1f%% at %.1f h\n%d deaths / %s patients\n%d studies\n(patient-weighted mean TTP)",
          anc_gpos$mort * 100, anc_gpos$ref_ttp,
          anc_gpos$n_deaths, format(anc_gpos$n_pts, big.mark = ","),
          anc_gpos$n_studies),
  "D  Gram-positive: absolute mortality probability"
)
