#| fig-cap: "Continuous TTP dose-response for mortality: Gram-negative (red) vs Gram-positive (blue) bacteremia. OR expressed relative to TTP = 24 h (dashed reference line). Shaded bands are 95% confidence intervals on the dose-response slope. Each doubling of TTP was associated with a 56% reduction in mortality odds in Gram-negative bacteremia (OR per 2× TTP = 0.44, 95% CI 0.38–0.51) and a 36% reduction in Gram-positive bacteremia (OR per 2× TTP = 0.64, 95% CI 0.51–0.80). Model: simulation-assisted mixed-effects logistic regression; representative TTP estimated from truncated log-normal distributions. Gram-negative: Prinsloo2023 excluded (anomalous group composition at 24 h cutpoint). Gram-positive: Minejima2019 excluded (72 h cutpoint reflects persistent bacteremia, a biologically distinct signal)."

bind_rows(curve_gneg, curve_gpos) |>
  ggplot(aes(x = ttp, y = median_OR, color = gram, fill = gram)) +
  geom_ribbon(aes(ymin = lo, ymax = hi), alpha = 0.12, color = NA) +
  geom_line(linewidth = 1.4) +
  geom_hline(yintercept = 1, linetype = "dashed",
             color = "gray40", linewidth = 0.7) +
  annotate("text", x = 35.5, y = 7.2,
           label = "Gram-negative\nOR×0.44 per 2× TTP\n(56% lower odds)",
           size = 2.9, color = "#E41A1C", hjust = 1, fontface = "italic") +
  annotate("text", x = 35.5, y = 4.5,
           label = "Gram-positive\nOR×0.64 per 2× TTP\n(36% lower odds)",
           size = 2.9, color = "#377EB8", hjust = 1, fontface = "italic") +
  scale_color_manual(values = c("Gram-negative" = "#E41A1C",
                                "Gram-positive" = "#377EB8")) +
  scale_fill_manual( values = c("Gram-negative" = "#E41A1C",
                                "Gram-positive" = "#377EB8")) +
  scale_x_continuous(breaks = c(2, 4, 6, 8, 10, 12, 15, 18, 24, 30, 36),
                     limits = c(1.5, 37),
                     name   = "Time to positivity (hours)") +
  scale_y_continuous(limits = c(0, 8.5), breaks = 0:8,
                     name   = "Odds ratio for mortality vs TTP = 24 h") +
  labs(color = NULL, fill = NULL) +
  theme_minimal(base_size = 11) +
  theme(panel.grid.minor = element_blank(),
        legend.position  = "bottom",
